// File header comment
using System;
using System.Collections.Generic;
using static System.Math;
using Alias = System.Text.StringBuilder;

/* multi-line
   block comment */
namespace MyApp.Core
{
    /// <summary>XML doc comment</summary>
    /// <remarks>More docs</remarks>
    [Serializable]
    [Obsolete("Use Other instead")]
    public enum Color
    {
        Red = 1,
        Green, // enum member comment
        Blue
    }

    public struct Point
    {
        public int X;
        public int Y;
        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }
    }

    public interface IShape
    {
        double Area { get; }
        void Draw();
    }

    [AttributeUsage(AttributeTargets.Class)]
    public class MyAttribute : Attribute
    {
        public string Name { get; set; }
    }

    /// <summary>Shape class docs</summary>
    public class Shape : IShape
    {
        private int count = 0;
        protected static readonly string Label = "shape";
        public const double Pi = 3.14;
        private string verbatim = @"C:\path\to";
        private string interpolated = $"Count is {count}";
        private string rawInterp = $"Sum: {count + 1}";
        private char quote = '"';

        public double Area { get; private set; }

        public string Description
        {
            get { return "desc"; }
            set { Description = value; }
        }

        static Shape()
        {
            Label = "static";
        }

        public Shape()
        {
            count = 1;
        }

        public Shape(int c) : this()
        {
            count = c;
        }

        ~Shape()
        {
            count = -1;
        }

        public void Draw()
        {
            int local = 5; // local comment
            var s = "local string";
            Console.WriteLine($"Drawing {local}");
        }

        private static int Compute(int a, int b = 2)
        {
            return a * b;
        }
    }
}

