# Terraform configuration for web stack
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "3.1.0"
    }
  }
  backend "s3" {
    bucket = "my-tf-state"
    key    = "web/terraform.tfstate"
  }
}

provider "aws" {
  region = var.aws_region
  default_tags {
    tags = {
      Environment = var.environment
    }
  }
}

provider "random" {}

variable "aws_region" {
  description = "The AWS region to deploy into"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  type    = string
  default = "dev"
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Must be dev or prod."
  }
}

variable "instance_count" {
  type    = number
  default = 2
}

locals {
  name_prefix = "web-${var.environment}"
  common_tags = {
    Project = "web"
  }
}

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"] # Canonical
  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }
}

resource "aws_instance" "web" {
  count         = var.instance_count
  ami           = data.aws_ami.ubuntu.id
  instance_type = "t3.micro"
  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-${count.index}"
  })
  /* block
     comment */
  user_data = <<-EOT
    #!/bin/bash
    echo "hello ${var.environment}"
  EOT
}

resource "aws_s3_bucket" "assets" {
  bucket = "${local.name_prefix}-assets"
}

resource "random_pet" "suffix" {
  length = 2
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "5.0.0"
  name    = local.name_prefix
  cidr    = "10.0.0.0/16"
}

output "instance_ids" {
  description = "IDs of web instances"
  value       = aws_instance.web[*].id
}

output "bucket_name" {
  value = aws_s3_bucket.assets.bucket
}

args.command:
cd /tmp/probe-csharp-hcl-scopes
for n in config_file body block attribute identifier expression literal_value string number bool null object tuple array function_call comment heredoc template template_literal variable_expr traversal scope source file document unit; do
  err=$(/workspace/executable --hcl-query "($n) @x" --only-matching < q.tf 2>&1)
  case "$err" in
    *"Invalid node type"*) echo "$n: INVALID";;
    *"No input was in scope"*) echo "$n: valid, no match";;
    *"Impossible"*) echo "$n: impossible";;
    *) echo "$n: MATCH or other: $(echo "$err" | head -2 | tr '\n' '|')";;
  esac
done

cd /tmp/probe-csharp-hcl-scopes
for n in for_expr conditional operator unary binary paren list map set object_elem object_key key value index splat get_attr attr traversal_root relative_traversal template_interpolation template_for template_if quoted_template heredoc_template literal number_lit bool_lit null_lit var_keyword collection grouping function arguments name type source_file_body block_body label labels string_content escape_sequence interpolation directive if_directive for_directive endif else keyword predicate; do
  err=$(/workspace/executable --hcl-query "($n) @x" --only-matching < q.tf 2>&1)
  case "$err" in
    *"Invalid node type"*) : ;;
    *"No input was in scope"*) echo "$n: valid";;
    *"Impossible"*) echo "$n: valid(impossible-in-context)";;
    *) echo "$n: OTHER: $(echo "$err"|head -1)";;
  esac
done; echo done
